WITH filtered AS (SELECT id, order_id, product_id, quantity, ROUND(unit_price * 1.1, 2) unit_price_scaled FROM order_items WHERE order_id IN (4, 6, 20, 36)) SELECT id, order_id, quantity, unit_price_scaled, LEAD(quantity, 1) OVER (PARTITION BY order_id, product_id ORDER BY quantity ASC, id ASC) next_quantity, NTILE(4) OVER (PARTITION BY order_id ORDER BY quantity ASC, id ASC) quantity_bucket, ROW_NUMBER() OVER (ORDER BY unit_price_scaled DESC, id ASC) seq_no FROM filtered
